def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        if nanoseconds is None:
            raise ValueError("Nanoseconds cannot be None")
        if not isinstance(nanoseconds, int):
            raise TypeError("Nanoseconds must be an integer")

        if tz is None:
            from datetime import datetime
            return datetime.fromtimestamp(nanoseconds / 1e9)
        else:
            from datetime import datetime, timezone, timedelta
            tz_offset = timezone(timedelta(seconds=tz))
            return datetime.fromtimestamp(nanoseconds / 1e9, tz=tz_offset)
    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if not isinstance(value, timedelta):
        raise ValueError("Value must be an instance of timedelta")
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Expected a Point instance")

    return {'x': value.x, 'y': value.y}

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self.record.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return super().index(key)
    except ValueError:
        raise ValueError(f"{key} is not in the list")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    try:
        if not keys:
            return list(self.__dict__.values())
        else:
            return [self.__dict__[key] for key in keys]
    except KeyError as e:
        raise KeyError(f"Key {e} not found in the record.") from e

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        return dict(zip(self._fields, self))

    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self):
                raise IndexError(f"Index {key} is out of bounds")
            result[self._fields[key]] = self[key]
        elif isinstance(key, str):
            if key not in self._fields:
                result[key] = None
            else:
                result[key] = getattr(self, key)
        else:
            raise ValueError(f"Invalid key type: {type(key)}")

    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    try:
        if len(self.data) < 2:
            raise ValueError("Insufficient data to pop a 16-bit unsigned integer.")
        high_byte, low_byte = self.data[-2:]
        self.data = self.data[:-2]
        return (high_byte << 8) | low_byte
    except AttributeError:
        raise TypeError("Data container does not support indexing or slicing.")

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    from collections import namedtuple

    if not isinstance(name, str) or not name:
        raise ValueError("Name must be a non-empty string.")
    if not isinstance(fields, list) or not all(isinstance(field, str) for field in fields):
        raise ValueError("Fields must be a list of non-empty strings.")
    if not isinstance(srid_map, dict) or not all(isinstance(key, int) and isinstance(value, str) for key, value in srid_map.items()):
        raise ValueError("SRID map must be a dictionary with integer keys and string values.")

    class DynamicPoint(namedtuple(name, fields)):
        __slots__ = ()  # No additional attributes

        def __new__(cls, *args, srid=4326):
            if srid not in srid_map:
                raise ValueError(f"Invalid SRID: {srid}. Must be one of {list(srid_map.keys())}.")
            return super(DynamicPoint, cls).__new__(cls, *args)

        @property
        def srid(self):
            return srid_map[self._fields.index('srid')]

    return DynamicPoint

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

