def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        unique_classes = []
        for cls in classes:
            if cls not in unique_classes and all(not issubclass(c, cls) for c in unique_classes):
                unique_classes.append(cls)
        return unique_classes
    except TypeError:
        raise ValueError("All elements in the classes list must be classes.")

