    """Return attribute names and descriptions defined by interface."""
    try:
        if all:
            return self.__class__.ATTRIBUTES.items()
        else:
            return [(name, desc) for name, desc in self.__class__.ATTRIBUTES.items() if not name.startswith('_')]
    except AttributeError:
        return []

def names(self, all=False): # pylint:disable=redefined-builtin
