def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}

    diff = {}
    for key, value in d1.items():
        if key not in d2:
            diff[key] = value
        else:
            if isinstance(value, dict) and isinstance(d2[key], dict) and level != 1:
                sub_diff = difference(value, d2[key], level - 1)
                if sub_diff:
                    diff[key] = sub_diff
            elif value != d2[key]:
                diff[key] = value

    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or not all(isinstance(x, int) for x in coord):
        raise ValueError("Coordinate must be a tuple of integers.")
    if not isinstance(weight, (int, float)):
        raise ValueError("Weight must be an integer or float.")
    if any(x < 0 or x >= size for x, size in zip(coord, self.shape)):
        return
    self.histogram[coord] += weight

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        raise ValueError("The provided application does not have a spec.manifest attribute")

    for resource_key, resource in app.spec.manifest.items():
        if resource_key not in app.spec.observers:
            # Generate default observer schema for the resource
            default_observer = {
                "resource": resource_key,
                "poll_interval": 30,  # Example default poll interval in seconds
                "conditions": [
                    {"type": "Ready", "status": "True"}
                ]
            }
            if not app.spec.observers:
                app.spec.observers = {}
            app.spec.observers[resource_key] = default_observer

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style, then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be of type str or bytes")

    if not isinstance(params, (dict, list, tuple)):
        raise ValueError("params must be a dict or a sequence")

    if self.SQLParams.in_style in ("pyformat", "named", "format") and not isinstance(params, dict):
        raise ValueError("params must be a dict for named or format parameter styles")

    if self.SQLParams.in_style in ("qmark", "numeric", "ordinal") and not isinstance(params, (list, tuple)):
        raise ValueError("params must be a sequence for qmark, numeric, or ordinal parameter styles")

    if self.SQLParams.in_style == self.SQLParams.out_style:
        return sql, params

    if self.SQLParams.out_style == "pyformat":
        placeholders = {key: f"%({key})s" for key in params}
        formatted_sql = sql % placeholders

        return formatted_sql, params

    if self.SQLParams.out_style == "named":
        placeholders = {key: f":{key}" for key in params}
        formatted_sql = sql % placeholders

        return formatted_sql, params

    if self.SQLParams.out_style == "format":
        placeholders = {key: f"%s" for key in params}
        formatted_sql = sql % placeholders

        return formatted_sql, list(params.values())

    if self.SQLParams.out_style == "qmark":
        assert isinstance(params, (list, tuple)), "params must be a sequence for qmark style"
        formatted_sql = sql % ("?" * len(params))

        return formatted_sql, params

    if self.SQLParams.out_style == "numeric":
        assert isinstance(params, (list, tuple)), "params must be a sequence for numeric style"
        placeholders = ":" + ":".join(str(i + 1) for i in range(len(params)))
        formatted_sql = sql % placeholders

        return formatted_sql, params

    if self.SQLParams.out_style == "ordinal":
        assert isinstance(params, (list, tuple)), "params must be a sequence for ordinal style"
        formatted_sql = sql % ("%" + "%" * (len(params) - 1))

        return formatted_sql, params

    raise ValueError(f"Unsupported out-style parameter format: {self.SQLParams.out_style}")

