def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, (list, tuple)):
        raise ValueError("manifest_files must be a list or tuple.")
    if not isinstance(digests_used, (list, tuple)):
        raise ValueError("digests_used must be a list or tuple.")

    for manifest in manifest_files:
        if not isinstance(manifest, dict):
            raise ValueError("Each manifest file must be a dictionary.")

        for file_digest in manifest.get('digests', []):
            if 'digest' not in file_digest:
                raise ValueError("Each file digest entry must have a 'digest' key.")

            if file_digest['digest'] not in digests_used:
                raise ValueError(f"Digest {file_digest['digest']} is present in the manifest but not used.")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The provided prior object is not an InventoryValidator instance.")

    if not hasattr(self, 'inventory') or not hasattr(prior, 'inventory'):
        raise ValueError("Both self and prior objects must have an inventory attribute.")

    for item_id, item in self.inventory.items():
        if item_id not in prior.inventory:
            raise ValueError(f"Item with ID {item_id} is present in the current inventory but not in the prior inventory.")

        for key, value in item.items():
            if key not in prior.inventory[item_id]:
                raise ValueError(f"Key {key} for item ID {item_id} is present in the current inventory but not in the prior inventory.")
            if value < prior.inventory[item_id][key]:
                raise ValueError(f"Value for key {key} of item ID {item_id} in the current inventory is less than the value in the prior inventory.")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    try:
        version_data = inventory.get(version)
        if not version_data:
            raise ValueError(f"Version {version} not found in inventory.")

        for logical_path, content_files in version_data.items():
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].update(content_files)

        # Include potential duplicates from later versions
        later_versions = [v for v in inventory if v > version]
        for v in later_versions:
            later_version_data = inventory.get(v, {})
            for logical_path, content_files in later_version_data.items():
                if logical_path in logical_path_map:
                    logical_path_map[logical_path].update(content_files)

    except Exception as e:
        raise ValueError(f"Error processing inventory for version {version}: {str(e)}")

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list.")

    for file_id, file_info in fixity.items():
        if file_id not in manifest_files:
            raise ValueError(f"File ID '{file_id}' in fixity block is not listed in the manifest.")

        if not isinstance(file_info, dict):
            raise ValueError(f"File info for '{file_id}' must be a dictionary.")

        if 'algorithm' not in file_info or 'digest' not in file_info:
            raise ValueError(f"File info for '{file_id}' must contain 'algorithm' and 'digest' keys.")

        if not isinstance(file_info['algorithm'], str) or not isinstance(file_info['digest'], str):
            raise ValueError(f"Algorithm and digest for '{file_id}' must be strings.")

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except FileNotFoundError:
        raise ValueError(f"The path {path} does not exist.")
    except PermissionError:
        raise ValueError(f"Permission denied for accessing the path {path}.")
    except Exception as e:
        raise ValueError(f"An error occurred while accessing the path {path}: {str(e)}")

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise ValueError("Content must be a string")

    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                return result[0]
        except Exception as e:
            # Handle any exceptions that may occur during xpath evaluation
            print(f"Error evaluating xpath {xpath}: {e}")
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        indent_str = '  ' * indent
        if debug:
            return f"{indent_str}{self.__class__.__name__}({self.__dict__})"
        else:
            return f"{indent_str}{self.__class__.__name__}()"
    except Exception as e:
        return f"{indent_str}<Error generating pretty representation: {str(e)}>")

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    def apply_absorption(expr1, expr2):
        if expr1 == expr2[0] and (expr2[1] == '|' or expr2[1] == '&'):
            if expr1 == expr2[2] or expr2[2] == ('~', expr1):
                return expr1
        return None

    def apply_negative_absorption(expr1, expr2):
        if expr2[1] == '|' and expr2[0] == ('~', expr1):
            return ('&', expr1, expr2[2])
        if expr2[1] == '&' and expr2[2] == ('~', expr1):
            return ('|', expr1, expr2[0])
        return None

    new_args = deepcopy(args)
    i = 0
    while i < len(new_args):
        absorbed = False
        for j in range(len(new_args)):
            if i != j:
                if isinstance(new_args[i], tuple) and isinstance(new_args[j], tuple):
                    result = apply_absorption(new_args[i][0], new_args[j])
                    if result:
                        new_args[i] = result
                        del new_args[j]
                        absorbed = True
                        break
                    result = apply_negative_absorption(new_args[i][0], new_args[j])
                    if result:
                        new_args[i] = result
                        del new_args[j]
                        absorbed = True
                        break
        if not absorbed:
            i += 1

    return new_args

