            func.vcs_handlers = {}
        func.vcs_handlers[vcs] = method
        return func
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        for obj in self:
            num_objects += 1
            is_valid = True

            if validate_objects:
                if not obj.is_valid():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj} is not valid.")

            if check_digests:
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Digest mismatch for object {obj}.")

            if is_valid:
                good_objects += 1

    except Exception as e:
        if show_warnings:
            print(f"An error occurred during validation: {e}")

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    try:
        if not self.storage_root.exists():
            self.storage_root.mkdir(parents=True)
        # Create required directories
        for dir_name in ['ocfl_layout.json', 'inventory.json', 'versions']:
            path = self.storage_root / dir_name
            if not path.exists():
                if path.suffix:  # It's a file, not a dir
                    path.touch()
                else:
                    path.mkdir()
        # Write default ocfl_layout.json
        ocfl_layout = {
            "head": "ocfl_layout.json",
            "id": "https://ocfl.io/1.0/spec/#layout",
            "type": "hashed-n-tuple",
            "digestAlgorithm": "sha512",
            "hashTupleLength": 2
        }
        with open(self.storage_root / 'ocfl_layout.json', 'w') as layout_file:
            import json
            json.dump(ocfl_layout, layout_file, indent=4)
    except Exception as e:
        raise RuntimeError(f"Failed to initialize OCFL storage root: {e}")

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    try:
        # Assuming self.root_inventory contains the root inventory data
        root_inventory = self.root_inventory.copy()
        seen_digests = set(root_inventory.keys())

        for version_dir in version_dirs:
            version_inventory_path = os.path.join(version_dir, 'inventory.json')
            if not os.path.exists(version_inventory_path):
                raise FileNotFoundError(f"Inventory file not found for version {version_dir} at {version_inventory_path}")

            with open(version_inventory_path, 'r') as f:
                version_inventory = json.load(f)

            for item, digest in version_inventory.items():
                seen_digests.add(item)
                if root_inventory.get(item) != digest:
                    root_inventory[item] = digest

        self.different_digests = {item: digest for item, digest in root_inventory.items() if item not in seen_digests}
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Error validating version inventories: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error during inventory validation: {e}")

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    namaste_file = os.path.join(path, '0=ocfl_1.0')

    try:
        if os.path.isdir(path):
            if os.path.isfile(namaste_file):
                return 'root'
            object_namaste_file = os.path.join(path, '0=ocfl_object_1.0')
            if os.path.isfile(object_namaste_file):
                return 'object'
            return 'unknown directory type'
        elif os.path.isfile(path):
            return 'file'
        else:
            return 'path does not exist'
    except Exception as e:
        return str(e)

