def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subclasses_list = cls.__subclasses__()
    for subclass in subclasses_list:
        subclasses_list.extend(subclasses(subclass))
    return subclasses_list

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")

    base = len(alphabet)
    result = 0
    for char in string:
        try:
            digit = alphabet.index(char)
        except ValueError:
            raise ValueError(f"Character '{char}' not found in alphabet.")
        result = result * base + digit
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise ValueError("Input must be a string.")
    return re.sub(r'^["\']|["\']$', '', name)

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path
    from typing import Optional, Union

    if filename is None:
        filename = Path(archive_path).stem

    tmp_path = Path(tmp_path)
    tmp_path.mkdir(parents=True, exist_ok=True)
    repo_path = tmp_path / filename
    repo_path.mkdir(parents=True, exist_ok=True)

    try:
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(
                ['tar', '-xzf', archive_path, '-C', repo_path],
                check=True
            )
        elif archive_path.endswith('.zip'):
            subprocess.run(
                ['unzip', archive_path, '-d', repo_path],
                check=True
            )
        else:
            raise ValueError("Unsupported archive format")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error extracting archive: {e}")

    return repo_path.resolve().as_uri()

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError(f"Invalid frequency format: {frequency}")

        count = int(parts[0])
        unit = parts[1].lower()

        if unit in ["seconds", "second"]:
            return datetime.timedelta(seconds=count)
        elif unit in ["minutes", "minute"]:
            return datetime.timedelta(minutes=count)
        elif unit in ["hours", "hour"]:
            return datetime.timedelta(hours=count)
        elif unit in ["days", "day"]:
            return datetime.timedelta(days=count)
        elif unit in ["weeks", "week"]:
            return datetime.timedelta(weeks=count)
        else:
            raise ValueError(f"Unknown time unit: {unit}")

    except (IndexError, ValueError) as e:
        raise ValueError(f"Invalid frequency: {frequency}") from e

