def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if ':' in matcher:
        name, default = matcher.split(':', 1)
    else:
        name, default = matcher, None

    value = os.getenv(name)
    if value is None:
        if default is None:
            raise ValueError(f"Environment variable '{name}' is not set and no default value was provided.")
        value = default

    return value

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise ValueError("Pattern must be a string")

    if strip:
        pattern = pattern.strip()

    try:
        regex_pattern = re.compile(pattern)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}")

    return regex_pattern

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if not isinstance(commands, list) or not commands:
            raise ValueError("Commands must be a non-empty list.")
        if not isinstance(args, list):
            raise ValueError("Arguments must be a list.")

        full_command = commands + args

        if verbose:
            print("Running command:", ' '.join(full_command))

        stderr = subprocess.DEVNULL if hide_stderr else None

        result = subprocess.run(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True
        )

        if verbose:
            print("Command output:\n", result.stdout)

        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, result.args, output=result.stdout, stderr=result.stderr)

        return result.stdout

    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with return code", e.returncode)
        raise
    except Exception as e:
        if verbose:
            print("An error occurred:", e)
        raise

