def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    configs = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as config_file:
                config.read_file(config_file)
        except Exception as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=None, exc_info=True))
            continue

        if resolve_env:
            for section in config.sections():
                for key, value in config.items(section):
                    try:
                        config.set(section, key, os.path.expandvars(value))
                    except Exception as e:
                        log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error resolving environment variables in {section}:{key} = {value}: {str(e)}", args=None, exc_info=True))

        # Apply overrides
        for section, settings in overrides.items():
            if section in config:
                for key, value in settings.items():
                    config.set(section, key, value)

        configs[filename] = {section: dict(config.items(section)) for section in config.sections()}

    return configs, log_records

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if not isinstance(values, (list, tuple, set)):
        raise TypeError("values must be an iterable of strings")

    bookmarks = []
    for value in values:
        if not isinstance(value, str):
            raise ValueError("Each value must be an ASCII string")
        if not all(ord(c) < 128 for c in value):
            raise ValueError("Each value must be an ASCII string")
        bookmarks.append(value)

    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple, set, frozenset, str, bytes)):
        sequence = seq
    else:
        try:
            sequence = list(seq)
        except TypeError:
            raise TypeError("Provided argument is not a sequence or iterable")

    return sequence, type(sequence)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, (type, tuple)):
        raise TypeError("iface must be a class or a tuple of classes")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")

    if tentative:
        return issubclass(candidate, iface) or any(issubclass(base, iface) for base in candidate.__bases__)
    else:
        return issubclass(candidate, iface)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc
    metas = [b.__class__ for b in bases if isinstance(b, type)]
    if not metas:
        return type
    elif len(set(metas)) == 1:
        return metas[0]
    else:
        raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    min_freq = min(self._freq.values())
    for key, freq in self._freq.items():
        if freq == min_freq:
            self._del_key(key)
            return key, self._store[key]
    raise KeyError("popitem(): dictionary is empty")

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = next(iter(self))
    return key, self.pop(key)

