def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if not isinstance(dt, datetime):
        raise ValueError("Input must be a datetime object")
    return dt.strftime("%Y-%m-%d %H:%M:%S")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    def linkify(match):
        url = match.group(0)
        return f'<a href="{url}" class="linkified" data-processed="true">{url}</a>'

    try:
        if not isinstance(text, str):
            raise ValueError("Input must be a string")

        # Basic regex for URLs (simplified version)
        url_pattern = r'https?://[^\s]+'
        processed_text = re.sub(url_pattern, linkify, text)

        return processed_text

    except Exception as e:
        raise ValueError(f"Error processing text links: {str(e)}")

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    import requests
    try:
        response = requests.head(url, allow_redirects=True)
        response.raise_for_status()
        return response.headers.get('Content-Type')
    except requests.RequestException:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False

    # Tags should be non-empty
    if not tag:
        return False

    # Tags should only contain alphanumeric characters and underscores
    if not all(char.isalnum() or char == '_' for char in tag):
        return False

    # Tags should not start with a digit
    if tag[0].isdigit():
        return False

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        if child.tag in result:
            raise ValueError(f"Duplicate child tag found: {child.tag}")
        result[child.tag] = child
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle is None or entity_handle is None:
        raise ValueError("Both sender_handle and entity_handle must be provided.")

    if sender_handle != entity_handle:
        raise ValueError(f"Sender handle ({sender_handle}) and entity handle ({entity_handle}) do not match.")

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not isinstance(url, str) or not url:
        raise ValueError("URL must be a non-empty string.")

    if document_path and not isinstance(document_path, str):
        raise ValueError("document_path must be a string if provided.")

    base_url = url.rstrip('/')
    nodeinfo_path = document_path or '/.well-known/nodeinfo'

    nodeinfo_document = {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.1",
                "href": f"{base_url}{nodeinfo_path}"
            }
        ]
    }

    return nodeinfo_document

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    try:
        # Try parsing as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try parsing as XRD
        try:
            from xml.etree import ElementTree as ET
            root = ET.fromstring(document)
            result = {}
            for elem in root.findall(".//xrd:Property", namespaces={'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}):
                name = elem.attrib.get('{http://docs.oasis-open.org/ns/xri/xrd-1.0}type')
                value = elem.text
                if name and value:
                    result[name] = value
            return result
        except ET.ParseError:
            raise ValueError("The document is not in a recognized format (JSON or XRD).")
        except Exception as e:
            raise ValueError(f"An error occurred while parsing the XRD document: {str(e)}")
    except Exception as e:
        raise ValueError(f"An error occurred while parsing the JSON document: {str(e)}")

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from xml.etree import ElementTree as ET

    if not isinstance(handle, str) or not handle:
        raise ValueError("Handle must be a non-empty string.")

    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger?resource=acct:{handle}")
        response.raise_for_status()
    except requests.RequestException as e:
        raise RuntimeError(f"Failed to retrieve webfinger document: {e}")

    try:
        root = ET.fromstring(response.content)
        webfinger_data = {}

        # Extract elements from the XML response
        for element in root.findall("{http://jabber.org/protocol/disco#info}xrd/{http://jabber.org/protocol/disco#info}link"):
            rel = element.get("rel")
            href = element.get("href")
            if rel and href:
                webfinger_data[rel] = href

        return webfinger_data
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse webfinger document: {e}")

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        import requests
        from lxml import etree
    except ImportError as e:
        raise RuntimeError("Required libraries are not installed: " + str(e))

    if not isinstance(host, str):
        raise ValueError("Host must be a string")

    try:
        response = requests.get(f"https://{host}/.well-known/host-meta")
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to retrieve host-meta from {host}: {str(e)}")

    try:
        xrd_content = response.content
        xrd = etree.fromstring(xrd_content)
    except etree.XMLSyntaxError as e:
        raise ValueError(f"Invalid XML syntax in host-meta response from {host}: {str(e)}")

    class XRD:
        def __init__(self, xml):
            self.xml = xml

    return XRD(xrd)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    current = dic
    for k in (key,) + keys[:-1]:
        if k not in current or not isinstance(current[k], dict):
            current[k] = {}
        current = current[k]
    if keys:
        current[keys[-1]] = val
    else:
        current[key] = val

def list_of_file_names(settings_dirs, spec_option):
    """Create a list of file names from the given directories based on the spec option.

    Parameters:
        settings_dirs (list of str): List of directory paths.
        spec_option (str): Specification option to filter files.

    Returns:
        list of str: List of file names that match the spec option.
    """
    import os

    file_names = []
    try:
        for directory in settings_dirs:
            if not os.path.isdir(directory):
                raise ValueError(f"The path {directory} is not a valid directory.")
            for file_name in os.listdir(directory):
                if file_name.endswith(spec_option):
                    file_names.append(os.path.join(directory, file_name))
    except Exception as e:
        print(f"An error occurred: {e}")

    return file_names

