def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    import yaml

    if not yaml_file:
        raise ValueError("yaml_file path must be provided")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {e}")
    except FileNotFoundError:
        raise IRValidatorException(f"YAML file {yaml_file} not found")
    except Exception as e:
        raise IRValidatorException(f"An error occurred while reading the YAML file {yaml_file}: {e}")

    required_fields = {'name', 'version', 'description'}  # Example required fields
    missing_fields = required_fields - set(data.keys())

    if missing_fields:
        raise IRValidatorException(f"Mandatory fields missing in YAML file {yaml_file}: {', '.join(missing_fields)}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    try:
        if 'include' not in parser_dict:
            return parser_dict

        include_directive = parser_dict.pop('include')
        if not isinstance(include_directive, dict):
            raise ValueError("Include directive must be a dictionary.")

        for key, value in include_directive.items():
            if key in parser_dict:
                raise ValueError(f"Duplicate key '{key}' found in spec file.")
            parser_dict[key] = value

        return parser_dict

    except Exception as e:
        raise ValueError(f"Error resolving include directive: {str(e)}")

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        defaults = {}
        for arg in self.spec.arguments:
            if arg.default is not None:
                defaults[arg.name] = arg.default
            elif hasattr(self, arg.name):
                defaults[arg.name] = getattr(self, arg.name)
            else:
                defaults[arg.name] = None
        return defaults
    except AttributeError as e:
        raise ValueError(f"Specification is not properly set or argument is missing: {str(e)}")

