def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_args = []
    try:
        for option in options_spec:
            required_when = option.get('required_when')
            if required_when:
                condition_key = required_when.get('arg')
                condition_value = required_when.get('equals')
                if args.get(condition_key) == condition_value:
                    matched_args.append(option.get('name'))
    except (AttributeError, TypeError, KeyError):
        pass  # Ignore if any of the expected keys or types are not found
    return matched_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for arg_name, (value, max_length) in args.items():
        if not isinstance(value, str):
            continue  # Skip non-string values
        if len(value) > max_length:
            raise ValueError(f"The length of '{arg_name}' exceeds the maximum allowed length of {max_length}.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    try:
        for arg_name, arg_value in args.items():
            if hasattr(self, 'choices'):
                if arg_name in self.choices and arg_value not in self.choices[arg_name]:
                    raise ValueError(f"Invalid value for {arg_name}: {arg_value}. Available choices are: {self.choices[arg_name]}")
    except AttributeError:
        raise AttributeError("The 'choices' attribute is not defined.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not hasattr(self, 'min_max_values'):
        raise AttributeError("The class instance must have a 'min_max_values' attribute defined.")

    if not isinstance(self.min_max_values, dict):
        raise TypeError("The 'min_max_values' attribute must be a dictionary.")

    for arg_name, (min_value, max_value) in self.min_max_values.items():
        if arg_name not in args:
            continue  # Skip arguments not defined in min_max_values

        value = args[arg_name]

        if not (min_value <= value <= max_value):
            raise ValueError(f"The value of '{arg_name}' must be between {min_value} and {max_value}, got {value}.")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary")

    control_args = {}
    nested_args = {}

    # Define which keys are considered control arguments
    control_keys = {'control_key1', 'control_key2', 'control_key3'}  # Update with actual control keys

    for key, value in args.items():
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is not None:
        if not isinstance(extra_vars, list):
            raise ValueError("extra_vars must be a list or None")

        for item in extra_vars:
            if not isinstance(item, dict):
                raise ValueError("Each item in extra_vars must be a dictionary")
            vars_dict.update(item)

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import shlex

    if not playbook_path:
        raise ValueError("Playbook path must be provided")

    command = ['ansible-playbook', playbook_path]

    if verbose:
        command.extend(['-v'] * verbose)

    if extra_vars:
        extra_vars_str = ','.join([f"{k}={v}" for k, v in extra_vars.items()])
        command.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for arg, value in ansible_args.items():
            if value is None:
                command.append(arg)
            else:
                command.extend([arg, str(value)])

    try:
        result = subprocess.run(command, check=True, text=True, capture_output=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible playbook execution failed: {e.stderr}") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the playbook: {str(e)}") from e

